```javascript
import { Group, Mesh, Cylinder, Sphere, PlaneGeometry, CylinderGeometry, SphereGeometry, PointLight } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { color, uniform, vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.position.copy(config.scenePosition || new THREE.Vector3(0, 0, 0));

  const cleanup = {
    timelines: [],
    resources: [],
    dispose() {
      this.timelines.forEach(t => t.kill());
      this.resources.forEach(r => r.dispose?.());
    }
  };

  root.userData.cleanup = () => cleanup.dispose();

  // Load primary gear from GLB
  const gearPromise = ctx.glbLoader.loadGLB(config.meshUrl).then(gltf => {
    const primaryGear = gltf.scene;
    primaryGear.scale.set(1.6, 1.6, 1.6);
    primaryGear.position.set(0, 0, 0);
    root.add(primaryGear);

    // Clone and position secondary gear — adjusted for tooth mesh
    // Primary radius: 0.8, secondary radius: 0.45, mesh distance: ~1.25
    const secondaryGear = primaryGear.clone();
    secondaryGear.scale.set(0.9, 0.9, 0.9);
    secondaryGear.position.set(1.3, 0, 0);
    root.add(secondaryGear);

    // Apply machined steel gear material with enhanced metalness and anisotropy
    const applyGearMaterial = (obj) => {
      obj.traverse(child => {
        if (child instanceof Mesh) {
          const newMat = new MeshStandardNodeMaterial({
            color: '#2a2a30', // Darker brushed steel for better contrast
            roughness: 0.5,
            metalness: 0.65, // Increased from 0.55 for stronger metallic read
            clearcoat: 0.2,
            clearcoatRoughness: 0.3,
            anisotropy: 0.8, // Enhanced anisotropy for radial catch-light
            emissive: '#0f0f14',
            emissiveIntensity: 0.08
          });
          child.material = newMat;
          cleanup.resources.push(newMat);
        }
      });
    };

    applyGearMaterial(primaryGear);
    applyGearMaterial(secondaryGear);

    // Jewel pivot sphere at primary hub — red accent with transmission
    const jewelGeo = new SphereGeometry(0.12, 32, 32);
    const jewelMat = new MeshPhysicalNodeMaterial({
      color: '#ff2a38',
      transmission: 0.6,
      ior: 1.76,
      emissive: '#ff2a38',
      emissiveIntensity: 1.8,
      roughness: 0.2,
      metalness: 0.0,
      side: 2 // DoubleSide for transmission
    });
    const jewel = new Mesh(jewelGeo, jewelMat);
    jewel.position.set(0, 0, 0);
    root.add(jewel);
    cleanup.resources.push(jewelGeo, jewelMat);

    // Arbor shafts (ink cylinders) — darker, non-metallic
    const arborGeo = new CylinderGeometry(0.05, 0.05, 0.8, 16);
    const arborMat = new MeshStandardNodeMaterial({
      color: '#0a0a0f',
      roughness: 0.8,
      metalness: 0.0,
      emissive: '#000000',
      emissiveIntensity: 0.0
    });

    const arbor1 = new Mesh(arborGeo, arborMat);
    arbor1.position.set(0, 0, 0);
    arbor1.rotation.x = Math.PI / 2;
    root.add(arbor1);

    const arbor2 = new Mesh(arborGeo, arborMat.clone());
    arbor2.position.set(1.3, 0, 0);
    arbor2.rotation.x = Math.PI / 2;
    root.add(arbor2);

    cleanup.resources.push(arborGeo, arborMat);

    // Contact shadow ellipse — darker at base
    const shadowGeo = new PlaneGeometry(2.6, 1.2);
    const shadowMat = new MeshStandardNodeMaterial({
      color: '#000000',
      emissive: '#000000',
      roughness: 1.0,
      metalness: 0.0,
      transparent: true,
      opacity: 0.48, // Increased opacity for stronger shadow presence
      depthWrite: false
    });
    const shadow = new Mesh(shadowGeo, shadowMat);
    shadow.position.set(0.65, -1.2, -1.95);
    shadow.rotation.x = -Math.PI / 2;
    root.add(shadow);
    cleanup.resources.push(shadowGeo, shadowMat);

    // Setup gear rotation animation (phase-locked meshing)
    const gearState = { primaryAngle: 0, secondaryAngle: 0 };
    const updateGears = () => {
      gearState.primaryAngle += 0.08 * (1 / 60);
      gearState.secondaryAngle = -(0.08 * (16 / 9)) * (1 / 60);

      primaryGear.rotation.z = gearState.primaryAngle;
      secondaryGear.rotation.z = gearState.secondaryAngle;
    };

    const gearTimeline = gsap.timeline({ repeat: -1 });
    gearTimeline.to(gearState, {
      primaryAngle: Math.PI * 2,
      duration: (Math.PI * 2) / 0.08,
      ease: 'none',
      onUpdate: updateGears
    }, 0);

    cleanup.timelines.push(gearTimeline);
  });

  // Backdrop gradient plane with richer gradient field
  const backdropGeo = new PlaneGeometry(7, 6);
  const gradColor1 = uniform(color('#0b0b10'));
  const gradColor2 = uniform(color('#0d0d15'));
  const gradColor3 = uniform(color('#14141e'));

  const backdropMat = new MeshStandardNodeMaterial({
    colorNode: mix(
      mix(gradColor1, gradColor2, uv().y.clamp(0, 0.5)),
      gradColor3,
      uv().y.sub(0.5).clamp(0, 1).mul(2.0)
    ),
    emissive: '#05050a',
    emissiveIntensity: 0.06,
    roughness: 1.0,
    metalness: 0.0
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -3;
  root.add(backdrop);
  cleanup.resources.push(backdropGeo, backdropMat);

  // Rim/accent lighting — red/warm back light to illuminate gear edges
  const rimLight = new PointLight('#ff4444', 1.2, 4.0);
  rimLight.position.set(-1.5, 0.5, 1.5);
  root.add(rimLight);
  cleanup.resources.push(rimLight);

  // Subtle fill light from opposite side
  const fillLight = new PointLight('#4a6fa5', 0.6, 3.5);
  fillLight.position.set(1.8, -0.3, 0.8);
  root.add(fillLight);
  cleanup.resources.push(fillLight);

  // Text: headline "The going train"
  const headlineText = ctx.fontAtlas.createText('The going train', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: -0.34
  });
  headlineText.position.set(0, -1.7, 0.1);
  root.add(headlineText);

  // Text: caption "34 COMPONENTS / HAND-FINISHED"
  const captionText = ctx.fontAtlas.createText('34 COMPONENTS / HAND-FINISHED', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.44
  });
  captionText.position.set(0, -2.1, 0.1);
  root.add(captionText);

  // Apply orbit cinematic primitive (camera drift via time trigger)
  const orbitResult = ctx.primitives['orbit'](root, {
    radius: 0.2,
    period: (Math.PI * 2) / 0.08
  });
  if (orbitResult) {
    cleanup.timelines.push(orbitResult.timeline);
  }

  return root;
}
